using FMODUnity;
using LittleLeo.Variables;
using Spine.Unity;
using UnityEngine;
using UnityEngine.AddressableAssets;

namespace Astrea;

[CreateAssetMenu(fileName = "OmenClearingReward", menuName = "Data/Rewards/OmenClearingReward", order = 0)]
public class OmenClearingReward : ClearingReward
{
	private static readonly AGLog<OmenClearingReward> Log = new AGLog<OmenClearingReward>();

	[SerializeField]
	[Tooltip("AssetRefFixer will fill this")]
	public AssetReferenceT<SkeletonDataAsset> TelescopeSkeletonDataAssetInternalRef;

	[SerializeField]
	private GameObject telescopeParticlesPrefab;

	[SerializeField]
	private GameObjectReference telescopeRewardPropGameObjectReference;

	[SerializeField]
	private EventReference telescopeAnimationSFX;

	public SkeletonDataAsset telescopeSkeletonDataAsset
	{
		get
		{
			Log.Debug($"AnimationData:{this} will load SkeletonDataAsset assetGuid:{TelescopeSkeletonDataAssetInternalRef.AssetGUID}", this);
			return AGSingletonMonoBehaviour<AddressablesAssetReferenceManager>.Instance.LoadFromRef(TelescopeSkeletonDataAssetInternalRef);
		}
		set
		{
		}
	}

	protected override void InitializePropPrefab(GameObject rewardPropGameObject)
	{
		if (telescopeRewardPropGameObjectReference.value == null)
		{
			telescopeRewardPropGameObjectReference.value = rewardPropGameObject;
		}
		rewardPropGameObject.GetComponent<TelescopeRewardProp>().InitializeTelescope(telescopeSkeletonDataAsset, telescopeParticlesPrefab, telescopeAnimationSFX);
	}
}
